WITH s0 AS (SELECT * FROM features),
s1 AS (SELECT *, (close_sma24_distance_atr < -2.5) AS _condition_0 FROM s0),
s2 AS (SELECT *, CASE WHEN count(_condition_0) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 17 PRECEDING AND CURRENT ROW) = 18 THEN bool_or(_condition_0) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 17 PRECEDING AND CURRENT ROW) END AS _condition_1 FROM s1),
s3 AS (SELECT *, (close_sma24_distance_atr > -0.5) AS _condition_2 FROM s2),
s4 AS (SELECT *, (close_sma24_distance_atr < 0.0) AS _condition_3 FROM s3),
s5 AS (SELECT *, (_condition_1 AND _condition_2 AND _condition_3) AS _condition_4 FROM s4),
s6 AS (SELECT *, (efficiency_24 < 0.35) AS _condition_5 FROM s5),
s7 AS (SELECT *, (_condition_4 AND _condition_5) AS _condition_6 FROM s6),
s8 AS (SELECT *, (return_6_atr > 0.0) AS _condition_7 FROM s7),
s9 AS (SELECT *, (_condition_6 AND _condition_7) AS _condition_8 FROM s8),
s10 AS (SELECT *, (close_sma24_distance_atr > 2.5) AS _condition_9 FROM s9),
s11 AS (SELECT *, CASE WHEN count(_condition_9) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 17 PRECEDING AND CURRENT ROW) = 18 THEN bool_or(_condition_9) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 17 PRECEDING AND CURRENT ROW) END AS _condition_10 FROM s10),
s12 AS (SELECT *, (close_sma24_distance_atr < 0.5) AS _condition_11 FROM s11),
s13 AS (SELECT *, (close_sma24_distance_atr > 0.0) AS _condition_12 FROM s12),
s14 AS (SELECT *, (_condition_10 AND _condition_11 AND _condition_12) AS _condition_13 FROM s13),
s15 AS (SELECT *, (efficiency_24 < 0.35) AS _condition_14 FROM s14),
s16 AS (SELECT *, (_condition_13 AND _condition_14) AS _condition_15 FROM s15),
s17 AS (SELECT *, (return_6_atr < 0.0) AS _condition_16 FROM s16),
s18 AS (SELECT *, (_condition_15 AND _condition_16) AS _condition_17 FROM s17),
s19 AS (SELECT *, (close_sma24_distance_atr >= 0.5) AS _condition_18 FROM s18),
s20 AS (SELECT *, (close_sma24_distance_atr <= -0.5) AS _condition_19 FROM s19)
SELECT instrument, bar_open_time, bar_close_time, coalesce(_condition_8, FALSE) AS entry_long, coalesce(_condition_17, FALSE) AS entry_short, coalesce(_condition_18, FALSE) AS exit_long, coalesce(_condition_19, FALSE) AS exit_short FROM s20 ORDER BY instrument, bar_open_time
